#!/usr/bin/env node
// Builds scripts/preview.bundle.mjs (the preview CLI) and scripts/check-result.bundle.mjs (the hunter-side result check), each
// with its dependencies, schemas and templates inlined, so an agent or a hunter that can run commands needs only Node, not
// `npm ci`. Also writes the third-party notices for the bundled packages beside them.
// Development only (esbuild is a devDependency). tests/bundle.test.mjs checks that the committed files match a fresh build.
import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = fileURLToPath(new URL('..', import.meta.url));
export const BUNDLE = join(root, 'scripts/preview.bundle.mjs');
export const CHECK_BUNDLE = join(root, 'scripts/check-result.bundle.mjs');
export const NOTICES = join(root, 'scripts/preview.bundle.NOTICES.txt');
const banner = entry => `// Generated by \`npm run bundle\` from ${entry}. Do not edit; third-party notices: preview.bundle.NOTICES.txt`;

/** Both bundles and the notices as strings, without writing anything. */
export async function build() {
  const esbuild = await import('esbuild');
  const packages = new Map();
  const one = async entry => {
    // absWorkingDir pins the source-path comments esbuild writes, so the output does not depend on the caller's directory.
    const result = await esbuild.build({
      absWorkingDir: root, entryPoints: [entry], bundle: true, platform: 'node', format: 'esm', target: 'node20',
      write: false, metafile: true, legalComments: 'none', banner: { js: banner(entry) }, logLevel: 'silent',
    });
    // Every bundled npm package, with its license text, for redistribution.
    for (const input of Object.keys(result.metafile.inputs)) {
      const m = /node_modules\/((?:@[^/]+\/)?[^/]+)\//.exec(input);
      if (m && !packages.has(m[1])) packages.set(m[1], join(root, 'node_modules', m[1]));
    }
    return result.outputFiles[0].text;
  };
  const bundle = await one('scripts/preview.mjs');
  const checkBundle = await one('scripts/check-result.mjs');
  const sections = [];
  for (const [name, dir] of [...packages].sort(([a], [b]) => a.localeCompare(b))) {
    const pkg = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
    const license = ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'license'].map(f => join(dir, f)).find(existsSync);
    sections.push(`${name}@${pkg.version} (${pkg.license})\n\n${license ? (await readFile(license, 'utf8')).trim() : 'No license file shipped; see the package metadata.'}`);
  }
  const notices = `Third-party software bundled into preview.bundle.mjs and check-result.bundle.mjs\n\n${sections.join('\n\n' + '-'.repeat(72) + '\n\n')}\n`;
  return { bundle, checkBundle, notices };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { bundle, checkBundle, notices } = await build();
  await writeFile(BUNDLE, bundle);
  await writeFile(CHECK_BUNDLE, checkBundle);
  await writeFile(NOTICES, notices);
  console.log(`wrote ${BUNDLE} (${bundle.length} bytes), ${CHECK_BUNDLE} (${checkBundle.length} bytes) and ${dirname(NOTICES)}/preview.bundle.NOTICES.txt`);
}
